public sealed class PaymentService(ILogger<PaymentService> logger)
{
    public void OnDeclined(int orderId, string reason, Cart cart)
    {
        // Built before the call: no OrderId field, a new text per order
        logger.LogWarning($"Payment declined for order {orderId}: {reason}");
        // Calls cart.ToString() even when Debug is off
        logger.LogDebug($"Cart at decline: {cart}");
    }
}

public sealed partial class PaymentService(ILogger<PaymentService> logger)
{
    public void OnDeclined(int orderId, string reason, Cart cart)
    {
        LogDeclined(orderId, reason);
        LogCart(cart); // checks IsEnabled(Debug) before any work
    }

    // The generator writes the bodies, using the logger parameter above
    [LoggerMessage(Level = LogLevel.Warning,
        Message = "Payment declined for order {OrderId}: {Reason}")]
    partial void LogDeclined(int orderId, string reason);

    [LoggerMessage(Level = LogLevel.Debug, Message = "Cart at decline: {Cart}")]
    partial void LogCart(Cart cart);
}
